", "children": [{"id": "786637cc-c17f-4567-962c-bf4e7ad8656a", "type": "concept", "title": "Respiratory, renal, cardiovascular, neurologic, and hepatic failure links"}, {"id": "08891043-36ae-4705-9fab-4e1f574d5bac", "type": "concept", "title": "Labs and trends that suggest worsening status"}, {"id": "d572bb2e-4a83-4315-83c8-bf2bddfe0d86", "type": "concept", "title": "ICU transfer considerations"}]}, {"id": "c7ebd0a7-7e28-40ce-9591-3af5a0144278", "type": "subtopic", "title": "Rapid response nursing", "description": "The goal is to act early, communicate clearly, and stabilize while help arrives.", "children": [{"id": "2253427a-59fe-45f1-8cb8-0939ec646ed5", "type": "concept", "title": "Rapid response criteria"}, {"id": "90647a3a-cf00-425f-9f0e-91adaa1d7e7f", "type": "concept", "title": "SBAR and closed-loop communication"}, {"id": "f876eee5-91f6-4518-bb9a-f859f24db56b", "type": "concept", "title": "Initial stabilization and documentation"}]}]}, {"id": "c53ca018-4281-4873-adcf-c3fbd4dd2e94", "type": "topic", "title": "Respiratory Failure, Critical Care Concepts, and Ventilation Awareness", "description": "Students build practical awareness of oxygenation failure, noninvasive support, mechanical ventilation, and ICU collaboration.", "children": [{"id": "bba9c6df-96d4-4d0c-b9e6-0f75c16d5f24", "type": "subtopic", "title": "Respiratory failure", "description": "Students learn to recognize oxygenation and ventilation failure before collapse.", "children": [{"id": "e7712b1a-b595-4162-b33f-548259c6930d", "type": "concept", "title": "Hypoxemia versus hypercapnia"}, {"id": "00c52360-6284-40b3-a0cd-eb79d5f58df6", "type": "concept", "title": "ABG interpretation and pulse oximetry limits"}, {"id": "29a549b0-2015-44cd-8250-c3133379b4cf", "type": "concept", "title": "Work of breathing and mental-status changes"}]}, {"id": "4aa9a4c2-81d6-4693-9769-f120195701a8", "type": "subtopic", "title": "Respiratory support", "description": "Med-surg nurses often care for patients before, after, or near higher-level respiratory support.", "children": [{"id": "e82b6acc-e0f8-4e22-abc5-31d82a3878c3", "type": "concept", "title": "Oxygen devices and high-flow nasal cannula awareness"}, {"id": "b250782d-57a6-4f94-86df-34efc2fe0433", "type": "concept", "title": "Noninvasive ventilation basics"}, {"id": "b5f9af5b-bdbe-4e55-ad7b-7b2ed79932a5", "type": "concept", "title": "Mechanical ventilation concepts and alarms awareness"}]}, {"id": "f2da31ca-96fa-4530-b6bb-64f1683b0584", "type": "subtopic", "title": "Critical-care collaboration", "description": "Students learn what to watch for and how to communicate across levels of care.", "children": [{"id": "abcfac1a-5e45-40d2-8630-319316faa298", "type": "concept", "title": "Respiratory therapy collaboration"}, {"id": "7c0116e2-71d1-42e9-8a7d-7982f7af345f", "type": "concept", "title": "Sedation, aspiration, and ventilator-associated risks"}, {"id": "034513a6-a77f-43d4-a680-3d122d13fe36", "type": "concept", "title": "ICU handoff and step-down monitoring"}]}]}, {"id": "f66d2d99-f969-44e7-b81b-de5112ad41a2", "type": "topic", "title": "High-Alert Medications, Blood Products, and Complex Pharmacology", "description": "This topic links high-risk therapies to monitoring, adverse effects, patient safety, and clinical decision-making.", "children": [{"id": "bceaf41c-b69c-497b-ae4a-dda5988c050b", "type": "subtopic", "title": "High-alert medication safety", "description": "Complex med-surg II patients often receive medications with narrow safety margins.", "children": [{"id": "c2860c7d-086b-41e5-8a6e-b20e27221448", "type": "concept", "title": "Insulin, anticoagulants, opioids, sedatives, vasopressors, and concentrated electrolytes"}, {"id": "fb586313-8f21-4597-9cf6-4ad70bfc6c71", "type": "concept", "title": "Independent double checks"}, {"id": "45fc874a-cc72-4ac0-ab84-de21042b3212", "type": "concept", "title": "Monitoring and antidote awareness"}]}, {"id": "7b841231-46f7-4fc3-a208-9d2d37b74989", "type": "subtopic", "title": "Anti-infective and immunologic therapy", "description": "Medication decisions affect infection control and immune function.", "children": [{"id": "b974afb0-6f62-473f-8757-badbee5b57d7", "type": "concept", "title": "Antibiotics, antivirals, antifungals, and stewardship"}, {"id": "dc9cf12e-ed9a-4248-ac40-4aea0a431785", "type": "concept", "title": "Immunosuppressants and biologics overview"}, {"id": "a09358c4-325a-4d50-bb4a-1c9ab989eb4c", "type": "concept", "title": "Adverse effects and patient teaching"}]}, {"id": "f49b5af2-708a-42a7-ab0d-dd02c6e00e92", "type": "subtopic", "title": "Medication reconciliation and polypharmacy", "description": "Complex adult care requires careful attention to interactions and transitions.", "children": [{"id": "07e98f60-46af-44de-abf0-5281a2e4e820", "type": "concept", "title": "Renal/hepatic dose considerations"}, {"id": "87c9a7cf-13de-41bf-80d7-3ab6d98e8194", "type": "concept", "title": "Drug-drug and drug-disease interactions"}, {"id": "50a738e3-8b87-4520-af78-de46f14cdd91", "type": "concept", "title": "Discharge medication teaching"}]}]}, {"id": "d1ab2aa3-e69c-4954-ae0c-80e4e9970720", "type": "topic", "title": "Palliative, End-of-Life, and Goals-of-Care Nursing", "description": "Students learn to support comfort, dignity, communication, ethical decisions, and family-centered end-of-life care.", "children": [{"id": "03e1d2d7-9c1e-48fb-9e67-e5b196c2c974", "type": "subtopic", "title": "Palliative nursing principles", "description": "Palliative care focuses on relief, function, dignity, and alignment with patient goals.", "children": [{"id": "ace967b2-ef09-4d4c-9440-b4e20c6ef3f5", "type": "concept", "title": "Symptom management"}, {"id": "de50b7db-547e-438e-94e6-559d102fa302", "type": "concept", "title": "Quality of life and function"}, {"id": "69bb92c3-3b8b-4a54-ae7a-55ac99903bcb", "type": "concept", "title": "Care across serious illness, not only at death"}]}, {"id": "8f785a46-8eef-497b-832f-49329cf5109f", "type": "subtopic", "title": "End-of-life care", "description": "Students learn to support patients and families during dying and bereavement.", "children": [{"id": "587e0252-8464-425f-bc20-621e967429a6", "type": "concept", "title": "Comfort-focused care"}, {"id": "af40ad89-f459-46c3-ba90-4db5447a405b", "type": "concept", "title": "Signs of active dying"}, {"id": "1f38278b-ebd7-47e6-83da-25e173a0ea8b", "type": "concept", "title": "Family presence, grief, and spiritual/cultural needs"}]}, {"id": "0e072671-4e2e-4530-9dbc-43914a2851ab", "type": "subtopic", "title": "Ethics and communication", "description": "Complex care often includes hard choices and emotionally charged conversations.", "children": [{"id": "1c134124-e2dc-45f4-aa3d-81409bd7dd34", "type": "concept", "title": "Advance directives and code status"}, {"id": "fd56f1c2-b867-4cac-965f-56b5fa1c84b8", "type": "concept", "title": "Goals-of-care discussions and nurse advocacy"}, {"id": "9e88b0d2-b2e0-497c-af10-937e0b1b57c0", "type": "concept", "title": "Moral distress and self-care"}]}]}, {"id": "5692a7ee-3820-44ea-bff2-42dbc311472a", "type": "topic", "title": "Prioritization, Delegation, Transitions, and NCLEX-Style Complex Cases", "description": "This module strengthens multiple-patient prioritization, delegation, discharge planning, and transition-to-practice judgment.", "children": [{"id": "7b5e53c7-ee63-43d0-bfed-43142b14109d", "type": "subtopic", "title": "Prioritization under complexity", "description": "Students learn to make decisions across multiple unstable or competing patient needs.", "children": [{"id": "1090de7b-159c-4cf4-8547-78550254415a", "type": "concept", "title": "ABCs, safety, acute change, and expected versus unexpected findings"}, {"id": "fea8c886-4979-4cc5-9ecb-7cbc8a0c093d", "type": "concept", "title": "Multiple-patient prioritization"}, {"id": "820ece72-5973-44b7-808b-ba14c792419b", "type": "concept", "title": "Trend-based decision-making"}]}, {"id": "ccdf0ef8-05a6-47e4-a617-88c7b33057b2", "type": "subtopic", "title": "Delegation and supervision", "description": "Safe delegation requires knowing scope, acuity, predictability, and follow-up needs.", "children": [{"id": "95164d69-0319-4ee6-900d-90b73c302075", "type": "concept", "title": "RN, LPN/LVN, and unlicensed assistive personnel roles"}, {"id": "f6d5939c-edc0-4785-88f8-82488ee709ed", "type": "concept", "title": "Task assignment and supervision"}, {"id": "d8a83732-e9ca-4ac3-996c-df470c7f56e1", "type": "concept", "title": "Feedback and accountability"}]}, {"id": "5c276c0e-975d-4905-b0e5-2814a2bfd9c7", "type": "subtopic", "title": "Transitions of care", "description": "Complex patients need careful handoff and discharge planning.", "children": [{"id": "a9ff0983-526a-44d4-932d-5c74856e0988", "type": "concept", "title": "Step-down, rehab, home health, and hospice referrals"}, {"id": "5836d459-fdcc-488e-92cc-bda51188e81c", "type": "concept", "title": "Readmission risk and teach-back"}, {"id": "41fdf331-4133-400a-ba30-fad4728ddb40", "type": "concept", "title": "NCLEX-style case analysis"}]}]}, {"id": "e088c918-4f6c-4ec1-babe-70f332218aa2", "type": "topic", "title": "Integrated Medical-Surgical Nursing II Simulation and Case Portfolio", "description": "Students synthesize advanced med-surg content through simulation, case analysis, documentation, handoff, and reflection.", "children": [{"id": "7301f628-6957-414f-bffa-7edf1d6923b6", "type": "subtopic", "title": "Simulation preparation", "description": "Students build a complete clinical picture before simulation.", "children": [{"id": "8ed7168d-b81a-477f-ac16-9a4da88353ae", "type": "concept", "title": "Patient history and comorbidities"}, {"id": "2fc7ee8c-a7c3-4179-8391-db4d9f0f32ee", "type": "concept", "title": "Pathophysiology and medication maps"}, {"id": "7d450bdd-19b6-4534-8418-21ab6a212210", "type": "concept", "title": "Priority hypotheses and safety risks"}]}, {"id": "28dca1a4-446a-4f1e-964a-2e768725ee73", "type": "subtopic", "title": "Simulation performance", "description": "The simulation asks students to act, not just recognize facts.", "children": [{"id": "047cbb7b-a8ef-46d4-b691-cac398495752", "type": "concept", "title": "Focused reassessment and interventions"}, {"id": "de0c8e42-3738-4afd-9327-237a5ffaac29", "type": "concept", "title": "Escalation, rapid response, and team communication"}, {"id": "bbaf0b03-bd75-460f-89ac-593e25c93fc1", "type": "concept", "title": "Documentation and handoff"}]}, {"id": "eec4f244-a7c9-462d-a7d9-a1ecd51d10cc", "type": "subtopic", "title": "Portfolio reflection", "description": "Reflection links performance to growth as a transitioning professional nurse.", "children": [{"id": "bed6534b-f031-469c-9eec-fac708d1cc19", "type": "concept", "title": "Clinical judgment self-assessment"}, {"id": "43d74fd1-d06a-412f-8865-d656126b5733", "type": "concept", "title": "Evidence-based rationale and missed cues"}, {"id": "4cfe9881-82a4-466c-b657-d5cefc9e06aa", "type": "concept", "title": "Plan for capstone, NCLEX, and transition to practice"}]}]}], "dbBacked": true}$msn2json$::jsonb,
