update public.learning_paths
set
  title = 'Medical-Surgical Nursing II',
  goal = 'Medical-Surgical Nursing II',
  summary = 'This course extends adult medical-surgical nursing into advanced acute-care and complex patient management. Students integrate renal, hematologic, oncologic, neurologic, burn, sensory, reproductive, immune, infectious, shock, multisystem, and palliative concepts with focused assessment, pharmacology, diagnostics, prioritization, delegation, and communication. The syllabus emphasizes early deterioration recognition, sepsis and shock response, critical-care awareness, complex medication safety, interprofessional coordination, and simulation-based transition-to-practice judgment.',
  data = $msn2json${"slug": "medical-surgical-nursing-ii", "title": "Medical-Surgical Nursing II", "description": "This course extends adult medical-surgical nursing into advanced acute-care and complex patient management. Students integrate renal, hematologic, oncologic, neurologic, burn, sensory, reproductive, immune, infectious, shock, multisystem, and palliative concepts with focused assessment, pharmacology, diagnostics, prioritization, delegation, and communication. The syllabus emphasizes early deterioration recognition, sepsis and shock response, critical-care awareness, complex medication safety, interprofessional coordination, and simulation-based transition-to-practice judgment.", "topics": [{"id": "4cb6ae03-6e8c-4566-a776-3a293d76af52", "type": "topic", "title": "Advanced Adult Health Clinical Judgment and Complex Care", "description": "Students learn to manage higher-acuity adult patients by integrating assessment, pathophysiology, pharmacology, prioritization, and safety.", "children": [{"id": "2a98119f-19e7-48c6-af59-a5a25b4dd473", "type": "subtopic", "title": "Complex clinical judgment", "description": "The point is to move from single-problem care to layered, unstable, and comorbid adult care.", "children": [{"id": "163d929b-76f1-47f6-aa15-25cd697e0e72", "type": "concept", "title": "Recognizing patterns across systems"}, {"id": "b42d7ff6-d254-41ba-b8a4-faa4b3b473f6", "type": "concept", "title": "Clinical judgment model and priority hypotheses"}, {"id": "9c097970-4c22-4924-977f-4a9cbecd7df0", "type": "concept", "title": "Complications, comorbidities, and changing patient status"}]}, {"id": "1fbda137-e3d2-438c-bf6e-ec3eaadbd28f", "type": "subtopic", "title": "Higher-acuity nursing role", "description": "Students learn how med-surg II bridges adult health and acute/critical-care thinking.", "children": [{"id": "c684f46e-c33b-44e5-b561-457a16e3f2bc", "type": "concept", "title": "Close monitoring and escalation"}, {"id": "2d5650cc-3b2c-4e75-994d-8d8cf34419ec", "type": "concept", "title": "Interprofessional coordination"}, {"id": "dfb3c916-d3e0-43d0-a496-1827a71f82a4", "type": "concept", "title": "Patient advocacy under uncertainty"}]}, {"id": "0d2ef199-3e2d-44a5-961b-87023b223d66", "type": "subtopic", "title": "Safety and equity in complex care", "description": "Complex patients need safe, individualized, culturally responsive care.", "children": [{"id": "ad01bd72-f89b-43c0-8a7f-936971fcbebc", "type": "concept", "title": "Health literacy and teach-back"}, {"id": "15f569dc-1dc1-4431-8038-f21c5af74895", "type": "concept", "title": "Cultural humility and trauma-informed care"}, {"id": "70be3a52-c201-4463-8325-ad4a3c79cb42", "type": "concept", "title": "Bias-aware assessment and pain/symptom evaluation"}]}]}, {"id": "bb7dd8ac-d2ec-4e02-aa19-cea5e9c56c3c", "type": "topic", "title": "Renal and Urinary Disorders", "description": "This module covers acute and chronic renal and urinary problems, fluid balance, dialysis awareness, and nursing priorities.", "children": [{"id": "eab0492f-6b24-4151-99c3-c0e1b7555950", "type": "subtopic", "title": "Renal assessment", "description": "Students learn to detect renal dysfunction through cues, labs, and fluid trends.", "children": [{"id": "146d5929-db6a-4dae-b009-956c3498c961", "type": "concept", "title": "Urine output, daily weights, edema, and fluid balance"}, {"id": "2f737749-9978-4c3e-b63c-be58e7ecdcc0", "type": "concept", "title": "BUN, creatinine, eGFR, electrolytes, and urinalysis"}, {"id": "b8a02ae3-0340-424f-80b7-7795dad2b838", "type": "concept", "title": "Nephrotoxic medication awareness"}]}, {"id": "3516e631-12a6-4326-a94f-f21cdccc2060", "type": "subtopic", "title": "Common disorders", "description": "The focus is nursing care for renal and urinary problems seen in adult acute care.", "children": [{"id": "a6bfbd2a-9715-489a-8f49-ff53f5e50db7", "type": "concept", "title": "Acute kidney injury and chronic kidney disease"}, {"id": "9a290f5a-b076-42a1-9d35-00ede61c31f1", "type": "concept", "title": "Urinary tract infection, pyelonephritis, and urinary retention"}, {"id": "fe6737d1-9f46-4e0e-844c-240b8ed46afc", "type": "concept", "title": "Kidney stones and obstructive uropathy"}]}, {"id": "8d7f4abd-589e-4392-bc2d-2fa9b18f8c48", "type": "subtopic", "title": "Renal therapies and teaching", "description": "Students learn supportive care, safety, and patient education around renal treatment.", "children": [{"id": "54748e5a-aee6-42e4-9566-0377d38e9bd3", "type": "concept", "title": "Fluid and electrolyte management"}, {"id": "deb88125-e6b6-4187-bca0-1a40f125973f", "type": "concept", "title": "Dialysis concepts and vascular access precautions"}, {"id": "7940354c-1da3-4c00-a47f-776f9b12ff6f", "type": "concept", "title": "Diet, medication, and follow-up teaching"}]}]}, {"id": "e05de6b8-cc91-47d5-b269-1002bf6c1159", "type": "topic", "title": "Hematologic and Coagulation Disorders", "description": "Students learn care for anemia, bleeding, clotting, transfusion needs, and hematologic instability.", "children": [{"id": "f685bd37-26b2-4547-b4da-5edda7101dee", "type": "subtopic", "title": "Hematologic assessment", "description": "Students connect blood disorders to oxygen delivery, perfusion, bleeding, and infection risk.", "children": [{"id": "15003ead-fdf4-4a57-a5ac-1a2ebfd0fade", "type": "concept", "title": "CBC interpretation"}, {"id": "5b1e7543-0535-4788-9229-05bb0874cdbe", "type": "concept", "title": "Signs of anemia, thrombocytopenia, and neutropenia"}, {"id": "71310615-04f0-4ad3-89c0-346f90a57d29", "type": "concept", "title": "Bleeding, bruising, fatigue, and infection cues"}]}, {"id": "e2f8157b-e0fb-4c85-b9b4-8ab55b10f9e6", "type": "subtopic", "title": "Coagulation and clotting", "description": "This area is high risk because both bleeding and thrombosis can deteriorate quickly.", "children": [{"id": "d481ea38-c71a-44d8-81b3-af277ea99c87", "type": "concept", "title": "DVT/PE risk and prevention"}, {"id": "d80675dd-b3ee-407b-b15f-0e3ebe91f268"